  // must not trip the gate, and local-only runner subcommands stay usable.
  const allowed = [
    "nixfmt flake.nix",
    "git commit -m 'nix support'",
    "cat nix/store/list.txt",
    "uv pip list",
    "uv run script.py", // project-env sync, same class as cargo build/go build
    "yarn run dlx-helper",
    "pipx list",
  ];

  for (const cmd of allowed) {
    test(`does not falsely detect: ${cmd}`, () => {
      expect(isDirectPackageInstallCommand(cmd)).toBe(false);
    });
  }
});

