218	      const fullPath = path.join(dir, name);
219	      try {
220	        fs.accessSync(fullPath, fs.constants.X_OK);
221	        binaries.set(name, fullPath);
222	        break;
223	      } catch {
224	        // not found
225	      }
226	    }
227	  }
