export function isDirectPackageInstallCommand(command: string): boolean {
  if (!command.trim()) {
    return false;
  }

  // `splitShellCommands` splits on unquoted operators/substitutions but KEEPS a
  // segment's quoted text inline (with the quote delimiters removed), so a
  // package-manager phrase used as data (`echo "nix shell"`) would still match.
  // Blank the quoted spans out of the RAW command first — a chained real
  // command (`echo "x"; nix run …`) lives outside the quotes and survives, so
  // it still splits into its own checkable segment.
  const deQuoted = stripQuotedSpans(command);
  const segments = splitShellCommands(deQuoted);
  // Fall back to the whole command if the lexer yields nothing, so a malformed
  // input can never silently skip the check.
  const candidates = segments.length > 0 ? segments : [deQuoted];

  return candidates.some((segment) => {
    // Unescape backslash escapes so an escaped executable name (`n\ix`) matches
    // its real form (`nix`).
    const normalized = unescapeShellToken(segment).trim().toLowerCase();
    if (!normalized) {
      return false;
    }
    return (
      DEFAULT_PACKAGE_MANAGER_DENY_PREFIXES.some((prefix) =>
        normalized.startsWith(prefix.toLowerCase())
      ) ||
      DIRECT_PACKAGE_INSTALL_PATTERNS.some((pattern) =>
        pattern.test(normalized)
      )
    );
  });
}

function normalizeToolName(name: string): string {
  return name.trim().toLowerCase();
}

