125	 * its real, canonical form. The shell drops a backslash before an ordinary
126	 * character (`n\ix` → `nix`, `u\vx` → `uvx`), so without this a single
127	 * backslash bypasses the whole package-install gate. We collapse `\<char>` to
128	 * `<char>` for every character; this is intentionally broad — it can only make
129	 * the detector match MORE, never introduce a false negative, and the segment
130	 * has already been split out of any quotes by the time we get here.
131	 */
132	function unescapeShellToken(segment: string): string {
133	  return segment.replace(/\\(.)/g, "$1");
134	}
135	
136	/**
137	 * Blank out single- and double-quoted spans so a package-manager phrase used
138	 * as DATA (a commit message, echoed help text) is not matched as a command.
139	 * Quoted text can never itself be a command, so replacing it with a space can
140	 * only remove false positives, never hide a real acquisition — a real command
141	 * lives OUTSIDE the quotes and survives untouched. Backslash-escaped quotes are
142	 * consumed as a pair so they don't spuriously open/close a span. Unbalanced
143	 * quotes leave the trailing text intact (conservative: still matched).
144	 */
145	function stripQuotedSpans(segment: string): string {
146	  let out = "";
147	  let quote: '"' | "'" | null = null;
148	  for (let i = 0; i < segment.length; i++) {
149	    const ch = segment[i];
150	    if (ch === "\\" && i + 1 < segment.length) {
151	      // Preserve an escaped char outside quotes (unescapeShellToken handles the
152	      // canonicalization); inside quotes it is dropped with the rest.
153	      if (!quote) {
154	        out += ch + segment[i + 1];
155	      }
156	      i++;
157	      continue;
158	    }
159	    if (quote) {
160	      if (ch === quote) {
161	        quote = null;
162	        out += " ";
163	      }
164	      continue;
165	    }
166	    if (ch === '"' || ch === "'") {
167	      quote = ch;
168	      out += " ";
169	      continue;
170	    }
171	    out += ch;
172	  }
173	  return out;
174	}
