    "n'i'x run nixpkgs#hello",
    '"npm" install lodash',
    'np"m" install x',
    "'uvx' cowsay",
    '"nix"-build x',
    "'nix'\\ shell x",
  ];
  for (const cmd of concatenated) {
    test(`canonicalizes quote-concat exec name: ${JSON.stringify(cmd)}`, () => {
      expect(isDirectPackageInstallCommand(cmd)).toBe(true);
