462	 * backend; undefined → local just-bash.
463	 */
464	export async function createEmbeddedBashOps(
465	  options: EmbeddedBashOpsOptions = {}
466	): Promise<BashOperations> {
467	  const runtimeProvider = getWorkerRuntimeProvider(options.runtimeProviderId);
468	  if (runtimeProvider) {
469	    if (!options.gw) {
470	      throw new Error(
471	        `runtime provider ${runtimeProvider.id} requires gateway parameters`
472	      );
473	    }
474	    if (options.mcpExposure === "cli") {
475	      console.warn(
476	        `[embedded] runtime provider ${runtimeProvider.id} routes bash through a remote runtime; MCP CLI exposure is unavailable there. Use MCP tools exposure instead.`
477	      );
478	    }
479	    console.log(
480	      `[embedded] bash backend active: ${runtimeProvider.id} runtime provider`
481	    );
482	    return runtimeProvider.createBashOps({ gw: options.gw });
483	  }
484	
485	  const { Bash, ReadWriteFs, NetworkAccessDeniedError } = await import(
486	    "just-bash"
487	  );
488	
489	  const rawWorkspaceDir =
490	    options.workspaceDir || process.env.WORKSPACE_DIR || "/workspace";
491	  // Canonicalize so the sandbox profile, ReadWriteFs root, bind mounts, and
492	  // realpath checks all see the same resolved path. macOS TMPDIR routes through
493	  // /var → /private/var symlinks; without realpath, the SBPL allow rule and
494	  // execFile cwd disagree.
495	  let workspaceDir = rawWorkspaceDir;
496	  try {
497	    fs.mkdirSync(rawWorkspaceDir, { recursive: true });
498	    workspaceDir = fs.realpathSync(rawWorkspaceDir);
499	  } catch {
500	    // Fall through with the raw value; downstream calls surface real errors.
501	  }
502	  const bashFs = new ReadWriteFs({ root: workspaceDir });
503	
504	  // Parse allowed domains from env var (set by gateway). Entries gate whether
505	  // network commands are registered at all — URL policy is enforced by the
506	  // gateway egress proxy, not here. Still validate shape and per-domain
507	  // syntax so a malformed env can't silently opt an agent into the network.
508	  const DOMAIN_PATTERN = /^[A-Za-z0-9.*_-]+(?::\d+)?$/;
509	  let allowedDomains: string[] = [];
510	  if (process.env.JUST_BASH_ALLOWED_DOMAINS) {
511	    try {
512	      const parsed: unknown = JSON.parse(process.env.JUST_BASH_ALLOWED_DOMAINS);
513	      if (!Array.isArray(parsed)) {
514	        throw new Error("expected a JSON array of domain strings");
515	      }
516	      const accepted: string[] = [];
517	      for (const entry of parsed) {
518	        if (typeof entry !== "string") continue;
519	        const trimmed = entry.trim();
520	        if (!trimmed) continue;
521	        if (!DOMAIN_PATTERN.test(trimmed)) {
522	          console.warn(
523	            `[embedded] Ignoring invalid JUST_BASH_ALLOWED_DOMAINS entry: ${JSON.stringify(entry)}`
524	          );
525	          continue;
526	        }
527	        accepted.push(trimmed);
528	      }
529	      allowedDomains = accepted;
530	    } catch (err) {
531	      console.error(
532	        `[embedded] Failed to parse JUST_BASH_ALLOWED_DOMAINS: ${
533	          err instanceof Error ? err.message : String(err)
534	        }`
535	      );
536	    }
537	  }
538	
539	  // A non-empty allow-list opts the agent into network commands; URL policy
540	  // itself is NOT enforced here. Built-in curl/wget route through the gateway
541	  // egress proxy (see egress-fetch.ts), where the per-agent grants synced
542	  // from this same allow-list — plus the global denylist, SSRF guard, and
543	  // egress judge — are enforced for the JS shim exactly as they are for
544	  // spawned binaries. just-bash's own NetworkConfig fetch would bypass all
545	  // of that (it never consults HTTP_PROXY), so it is deliberately unused.
546	  const egressFetch =
