126	 * `"nix"` → `nix`, `n"i"x` → `nix`, `n'i'x` → `nix`) and drop backslash escapes
127	 * (`n\ix` → `nix`). The detector matches against this canonical form so an
128	 * honestly-typed package manager is recognized however it is spelled.
129	 *
130	 * `dataStripped` additionally removes the CONTENTS of quoted spans, for a
131	 * segment whose leading command treats its quoted arguments as data (`echo`,
132	 * `cat`) — so a package name inside an echoed string is not a false positive.
133	 */
134	function canonicalizeSegment(segment: string): {
135	  code: string;
136	  dataStripped: string;
137	} {
138	  let code = "";
139	  let dataStripped = "";
140	  let quote: '"' | "'" | null = null;
141	  for (let i = 0; i < segment.length; i++) {
142	    const ch = segment[i];
143	    if (ch === "\\" && i + 1 < segment.length) {
144	      code += segment[i + 1];
145	      if (!quote) {
146	        dataStripped += segment[i + 1];
147	      }
148	      i++;
149	      continue;
150	    }
151	    if (quote) {
152	      if (ch === quote) {
153	        quote = null;
154	      } else {
155	        code += ch;
156	      }
157	      continue;
158	    }
159	    if (ch === '"' || ch === "'") {
160	      quote = ch;
161	      continue;
162	    }
163	    code += ch;
164	    dataStripped += ch;
165	  }
166	  return {
167	    code: code.trim().toLowerCase(),
168	    dataStripped: dataStripped.trim().toLowerCase(),
169	  };
170	}
171	
172	/**
173	 * Leading commands whose quoted arguments are purely passive DATA. For a
174	 * segment led by one of these, the quoted content is dropped before matching so
175	 * an echoed / concatenated package-manager phrase is not a false positive.
176	 * Deliberately NARROW: only commands that cannot execute a string argument.
177	 * Anything that can run code from an argument (`sh`/`bash`/`eval`, `git -c
178	 * alias=!…`, `rg --pre`, `awk`, `find -exec`, an unknown binary) is NOT here,
