217	  if (!command.trim()) {
218	    return false;
219	  }
220	
221	  const segments = splitShellCommands(command);
222	  const candidates = segments.length > 0 ? segments : [command];
223	
224	  return candidates.some((segment) => {
225	    const { code, dataStripped } = canonicalizeSegment(segment);
226	    if (!code) {
227	      return false;
228	    }
229	    // Drop quoted content only for a leading command whose quoted args are
230	    // purely passive data (`echo`, `cat`); otherwise match the full canonical
231	    // command. Enforcement does not depend on getting this right — the sandbox
232	    // binary filter blocks the resolved binary regardless (see the header).
233	    const target = QUOTED_ARG_IS_DATA_COMMANDS.has(leadingCommand(code))
234	      ? dataStripped
235	      : code;
236	    if (!target) {
237	      return false;
238	    }
239	    return (
240	      DEFAULT_PACKAGE_MANAGER_DENY_PREFIXES.some((prefix) =>
241	        target.startsWith(prefix.toLowerCase())
242	      ) ||
243	      DIRECT_PACKAGE_INSTALL_PATTERNS.some((pattern) => pattern.test(target))
244	    );
245	  });
