247	
248	function normalizeToolName(name: string): string {
249	  return name.trim().toLowerCase();
250	}
251	
252	export function normalizeToolList(value?: string | string[]): string[] {
253	  if (!value) {
254	    return [];
255	  }
256	  const rawList = Array.isArray(value) ? value : value.split(/[,\n]/);
257	  return rawList
258	    .map((entry) =>
259	      typeof entry === "string" ? entry.trim() : String(entry).trim()
260	    )
261	    .filter((entry) => entry.length > 0);
262	}
263	
264	function parseBashFilter(pattern: string): string | null {
265	  const match = pattern.match(/^Bash\(([^:]+):\*\)$/i);
266	  const prefix = match?.[1]?.trim();
267	  return prefix || null;
268	}
269	
270	function matchesToolPattern(toolName: string, pattern: string): boolean {
271	  const normalizedTool = normalizeToolName(toolName);
272	  const normalizedPattern = pattern.trim();
273	  const normalizedPatternLower = normalizedPattern.toLowerCase();
274	
275	  if (normalizedPattern === "*") {
276	    return true;
277	  }
278	
279	  if (normalizedPatternLower.endsWith("*")) {
280	    const prefix = normalizedPatternLower.slice(0, -1);
281	    return normalizedTool.startsWith(prefix);
282	  }
283	
284	  return normalizedTool === normalizedPatternLower;
285	}
286	
287	export function buildToolPolicy(params: {
288	  toolsConfig?: ToolsConfig;
289	  allowedTools?: string | string[];
290	  disallowedTools?: string | string[];
291	}): ToolPolicy {
292	  const allowedPatterns = normalizeToolList(params.allowedTools);
293	  const deniedPatterns = normalizeToolList(params.disallowedTools);
294	  const toolsConfig = params.toolsConfig;
295	  const strictMode = toolsConfig?.strictMode === true;
296	
297	  const mergedAllowed = [
298	    ...(toolsConfig?.allowedTools ?? []),
299	    ...allowedPatterns,
300	  ].map((p) => p.trim());
301	  const mergedDenied = [
302	    ...(toolsConfig?.deniedTools ?? []),
303	    ...deniedPatterns,
304	  ].map((p) => p.trim());
305	
306	  const bashAllowPrefixes = mergedAllowed
307	    .map((pattern) => parseBashFilter(pattern))
308	    .filter((prefix): prefix is string => Boolean(prefix));
309	
310	  const bashDenyPrefixes = mergedDenied
311	    .map((pattern) => parseBashFilter(pattern))
312	    .filter((prefix): prefix is string => Boolean(prefix));
313	
314	  const bashAllowAll = mergedAllowed.some((pattern) =>
315	    matchesToolPattern("bash", pattern)
316	  );
317	
318	  return {
319	    toolsConfig,
320	    allowedPatterns: mergedAllowed,
321	    deniedPatterns: mergedDenied,
322	    strictMode,
323	    bashPolicy: {
324	      allowAll: bashAllowAll,
325	      allowPrefixes: bashAllowPrefixes,
326	      denyPrefixes: [
327	        ...DEFAULT_PACKAGE_MANAGER_DENY_PREFIXES,
328	        ...bashDenyPrefixes,
329	      ],
330	    },
331	  };
332	}
333	
334	export function isToolAllowedByPolicy(
335	  toolName: string,
336	  policy: ToolPolicy
337	): boolean {
338	  const normalizedName = normalizeToolName(toolName);
339	  const { allowedPatterns, deniedPatterns, strictMode } = policy;
340	
341	  const explicitDenied = deniedPatterns.some(
342	    (pattern) =>
343	      !parseBashFilter(pattern) && matchesToolPattern(normalizedName, pattern)
344	  );
345	  if (explicitDenied) {
346	    return false;
347	  }
348	
349	  if (normalizedName === "bash") {
350	    if (strictMode) {
351	      const explicitlyAllowed = allowedPatterns.some((pattern) =>
352	        matchesToolPattern(normalizedName, pattern)
353	      );
354	      const hasCommandAllowlist = policy.bashPolicy.allowPrefixes.length > 0;
355	      return explicitlyAllowed || hasCommandAllowlist;
356	    }
357	    return true;
358	  }
359	
360	  if (!strictMode) {
361	    return true;
362	  }
363	
364	  return allowedPatterns.some((pattern) =>
365	    matchesToolPattern(normalizedName, pattern)
366	  );
367	}
368	
369	/**
370	 * Split a shell command into its individual sub-commands.
371	 *
372	 * A prefix-only allow/deny check is trivially bypassed by command chaining and
373	 * substitution: an allowed prefix (`git status`) followed by `;`, `&&`, `||`,
374	 * `|`, a newline, `$( … )`, or backticks runs an arbitrary second command that
375	 * the policy never inspects. To close that hole we evaluate the prefix check
376	 * against EVERY sub-command, not just the leading one.
377	 *
378	 * This is a deliberately conservative lexer — not a full shell parser. It walks
379	 * the string tracking single/double quotes and treats any of the shell control
380	 * operators, plus the boundaries of `$( … )` / backtick substitutions, as
381	 * segment separators. Substitution boundaries are split rather than recursed so
382	 * the substituted command body is checked as its own segment. Quoted operators
383	 * (e.g. `echo "a; b"`) are intentionally left intact — they are data, not a new
384	 * command — while unquoted ones start a new segment.
385	 */
386	function splitShellCommands(command: string): string[] {
387	  const segments: string[] = [];
388	  let current = "";
389	  let inSingle = false;
390	  let inDouble = false;
391	
392	  const push = () => {
393	    const trimmed = current.trim();
394	    if (trimmed) {
395	      segments.push(trimmed);
396	    }
397	    current = "";
398	  };
399	
400	  for (let i = 0; i < command.length; i++) {
401	    const ch = command[i];
402	    const next = command[i + 1];
403	
404	    if (inSingle) {
405	      // Quote delimiters are RETAINED in the segment so downstream consumers can
406	      // still see quoting (the package-install detector distinguishes quoted
407	      // data from quoted code). Prefix/allow checks key on the leading command
408	      // word, which quoting the delimiter never changes.
409	      current += ch;
410	      if (ch === "'") {
411	        inSingle = false;
412	      }
413	      continue;
414	    }
415	
416	    if (inDouble) {
417	      // Inside double quotes only `$( … )` / backticks introduce a new command;
418	      // everything else (including `;`, `&&`, `|`) is literal data.
419	      if (ch === '"') {
420	        inDouble = false;
421	        current += ch;
422	      } else if (ch === "$" && next === "(") {
423	        push();
424	        i++; // consume "("
425	      } else if (ch === "`") {
426	        push();
427	      } else {
428	        current += ch;
429	      }
430	      continue;
431	    }
432	
433	    if (ch === "'") {
434	      inSingle = true;
435	      current += ch;
436	      continue;
437	    }
438	    if (ch === '"') {
439	      inDouble = true;
440	      current += ch;
441	      continue;
442	    }
443	
444	    // Command-substitution boundaries become segment separators so the
445	    // substituted body is checked on its own.
446	    if (ch === "$" && next === "(") {
447	      push();
448	      i++; // consume "("
449	      continue;
450	    }
451	    // Process substitution: `<( … )` / `>( … )` runs the inner command, so the
452	    // boundary starts a new segment and the substituted body is checked on its
453	    // own (e.g. `cat <(rm -rf /)` must not let `rm` ride inside the `cat` segment).
454	    if ((ch === "<" || ch === ">") && next === "(") {
455	      push();
456	      i++; // consume "("
457	      continue;
458	    }
459	    if (ch === ")" || ch === "`") {
460	      push();
461	      continue;
462	    }
463	
464	    // Control operators: ; & && | || and newlines.
465	    if (ch === "\n" || ch === ";") {
466	      push();
467	      continue;
468	    }
469	    if (ch === "&" || ch === "|") {
470	      push();
471	      if (next === ch) {
472	        i++; // collapse && / ||
473	      }
474	      continue;
475	    }
476	
477	    current += ch;
478	  }
479	
480	  push();
481	  return segments;
482	}
483	
484	export function enforceBashCommandPolicy(
485	  command: string,
486	  policy: BashCommandPolicy
487	): void {
488	  if (!command.trim()) {
489	    return;
490	  }
491	
492	  const segments = splitShellCommands(command);
493	  if (segments.length === 0) {
494	    return;
495	  }
496	
497	  const hasAllowlist = !policy.allowAll && policy.allowPrefixes.length > 0;
498	
499	  for (const segment of segments) {
500	    const normalizedSegment = segment.toLowerCase();
501	    // Deny is checked against the CANONICAL form (quoting/escaping collapsed to
502	    // what the shell would execute), so `n\ix shell`, `"nix" shell`, and
503	    // `n"i"x shell` all resolve to `nix shell` and cannot slip a deny prefix.
504	    // Canonicalizing can only make a deny prefix match MORE, so it is safe.
505	    const denyTarget = canonicalizeSegment(segment).code;
506	
507	    const denied = policy.denyPrefixes.some((prefix) =>
508	      denyTarget.startsWith(prefix.toLowerCase())
509	    );
510	    if (denied) {
511	      throw new Error("Bash command denied by policy");
512	    }
513	
514	    if (hasAllowlist) {
515	      // Allow is checked against the RAW segment: a quoted/escaped command that
516	      // no longer matches an allow prefix must fall through to "not allowed",
517	      // never be spuriously permitted by canonicalizing.
518	      const allowed = policy.allowPrefixes.some((prefix) =>
519	        normalizedSegment.startsWith(prefix.toLowerCase())
520	      );
521	      if (!allowed) {
522	        throw new Error("Bash command not allowed by policy");
523	      }
524	    }
525	  }
526	}
