255	 * Resolve a just-bash virtual cwd to a real on-disk path. just-bash's
256	 * `CommandContext.cwd` is rooted at the `ReadWriteFs` root, but `child_process`
257	 * needs a host path. We realpath both sides and verify the resolved cwd stays
258	 * inside the workspace — defense in depth against a symlink that slipped past
259	 * `ReadWriteFs` (e.g. if `allowSymlinks` is ever enabled upstream).
260	 */
261	function resolveHostCwd(workspaceDir: string, virtualCwd: string): string {
262	  const trimmed = virtualCwd.startsWith("/") ? virtualCwd.slice(1) : virtualCwd;
263	  const candidate = trimmed ? path.join(workspaceDir, trimmed) : workspaceDir;
264	  let realCwd: string;
265	  let realWs: string;
266	  try {
267	    realCwd = fs.realpathSync(candidate);
268	    realWs = fs.realpathSync(workspaceDir);
269	  } catch {
270	    return workspaceDir;
271	  }
272	  if (realCwd !== realWs && !realCwd.startsWith(realWs + path.sep)) {
273	    throw new Error(
274	      `[embedded] cwd ${JSON.stringify(virtualCwd)} resolves outside workspace`
275	    );
