    // observable versus the safe builtin (which never prints it).
    fs.writeFileSync(fakeEnv, '#!/bin/sh\necho "HOST-ENV-RAN"\n', "utf8");
    fs.chmodSync(fakeEnv, 0o755);
    return { workspace, storeBin };
  }

