import { test, expect } from "bun:test";
test("probe xargs/find wrapping nix via builtin", async () => {
  const { Bash, InMemoryFs } = await import("just-bash");
  const bash = new Bash({ fs: new InMemoryFs() });
  const cmds = ["xargs -I{} nix run x", "echo x | xargs nix run", "find . -maxdepth 0 -exec nix run x ;", "timeout 5 nix run x", "nice -n 5 nix run x"];
  const lines: Record<string,string> = {};
  for (const cmd of cmds) {
    const r = await bash.exec(cmd);
    lines[cmd] = `exit ${r.exitCode} ${`${r.stdout??""}${r.stderr??""}`.includes("command not found")?"[notfound]":""}`;
  }
  expect(lines).toEqual({__marker:true});
});
EOF
bun test src/__tests__/zzz-probe.test.ts > /tmp/probe-out.txt 2>&1; rm -f src/__tests__/zzz-probe.test.ts; sed -n '/Received/,/^(fail)/p' /tmp/probe-out.txt

cat > src/__tests__/zzz-probe.test.ts <<'EOF'
import { test, expect } from "bun:test";
test("probe", async () => {
  const { Bash, InMemoryFs } = await import("just-bash");
  const bash = new Bash({ fs: new InMemoryFs() });
  const cmds = ["xargs -I{} nix run x", "echo x | xargs nix run", "find . -maxdepth 0 -exec nix run x ;", "timeout 5 nix run x", "nice -n 5 nix run x"];
  const out: string[] = [];
  for (const cmd of cmds) {
    const r = await bash.exec(cmd);
    const combined = `${r.stdout??""}${r.stderr??""}`;
    out.push(`${cmd} => exit=${r.exitCode} notfound=${combined.includes("command not found")}`);
  }
  expect(out.join(" ||| ")).toBe("MARKER");
});
EOF
bun test src/__tests__/zzz-probe.test.ts 2>&1 | grep -oE '"[^"]*=>[^"]*"' | head; rm -f src/__tests__/zzz-probe.test.ts

