/**
 * Choose which canonical form to match a segment against: the data-stripped
 * form (quoted spans blanked) when the leading command — past any `VAR=value`
 * assignments — treats its quoted arguments as passive DATA (`printf`, `echo`,
 * `cat`), otherwise the full `code` form. This is what stops `printf "nix run
 * docs"` from being read as a `nix run` invocation while still inspecting the
 * quoted body of a command that can execute it (`sh -c '…'`, `eval '…'`).
 */
function denyMatchTarget(code: string, dataStripped: string): string {
  const head = skipLeadingAssignments(code);
  const command = leadingCommand(code.slice(head));
  return QUOTED_ARG_IS_DATA_COMMANDS.has(command) ? dataStripped : code;

