import { expect, test } from "bun:test";
import { isDirectPackageInstallCommand } from "./src/runtime/tool-policy";

// A global regex reused across calls is a classic statefulness trap. Call the
// same input repeatedly and interleave inputs to prove there is no lastIndex
// carry-over between invocations.
test("repeated and interleaved calls are stable", () => {
  const yes = "bash -c 'uvx cowsay'";
  const no = "git commit -m 'nix shell support'";

  for (let i = 0; i < 5; i++) {
    expect(isDirectPackageInstallCommand(yes)).toBe(true);
    expect(isDirectPackageInstallCommand(no)).toBe(false);
  }

  for (let i = 0; i < 5; i++) {
    expect(isDirectPackageInstallCommand(yes)).toBe(true);
  }
  for (let i = 0; i < 5; i++) {
    expect(isDirectPackageInstallCommand(no)).toBe(false);
  }
});

test("multiple -c bodies in one command line", () => {
  expect(isDirectPackageInstallCommand("sh -c 'echo hi'; sh -c 'uvx x'")).toBe(
    true
  );
  expect(isDirectPackageInstallCommand("sh -c 'echo hi'; sh -c 'echo b'")).toBe(
    false
  );
});

