import { expect, test } from "bun:test";
import {
  buildToolPolicy,
  enforceBashCommandPolicy,
  isDirectPackageInstallCommand,
} from "./src/runtime/tool-policy";

test("blocker 1: phrase mid-quote", () => {
  for (const c of [
    "git commit -m 'document nix shell support'",
    "echo 'use uvx here'",
    "git commit -m 'we should apt install curl'",
    "git commit -m 'nix shell support'",
  ]) {
    console.log(`${isDirectPackageInstallCommand(c) ? "DENIED " : "allowed"}  ${c}`);
  }
  expect(true).toBe(true);
});

test("blocker 2: backslash-newline continuation", () => {
  const policy = buildToolPolicy({
    toolsConfig: { bash: { deny: ["rm "] } },
  } as never).bashPolicy;
  console.log("policy:", JSON.stringify(policy));
  const split = "r\\\nm -rf /tmp/x";
  console.log("input:", JSON.stringify(split));
  let threw = false;
  try {
    enforceBashCommandPolicy(split, policy);
  } catch (e) {
    threw = true;
    console.log("threw:", (e as Error).message);
  }
  console.log(threw ? "DENIED" : "ALLOWED (bypass)");
  expect(true).toBe(true);
});

