import { expect, test } from "bun:test";

// Proves the docstring claim: the spellings the text hint does not recognize
// are unreachable at the real boundary anyway, because just-bash only runs
// builtins plus registered commands and none of these interpreters are
// registered.
test("path/long-option/env spellings are not runnable via just-bash", async () => {
  const { Bash, InMemoryFs } = await import("just-bash");
  const bash = new Bash({ fs: new InMemoryFs() });

  for (const cmd of [
    "/bin/bash -c 'nix run x'",
    "bash --login -c 'nix run x'",
    "/usr/bin/env bash -c 'nix run x'",
    "zsh -c 'uvx x'",
    "dash -c 'uvx x'",
  ]) {
    const r = await bash.exec(cmd);
    expect(r.exitCode).toBe(127);
    expect(`${r.stdout ?? ""}${r.stderr ?? ""}`).toContain("command not found");
  }
});

