 * `c` may sit anywhere in a short-option cluster and may follow other options
 * given as separate words, so `-lc`, `-ce`, `-cx` and `bash -euo pipefail -c`
 * all reach the body. Matching only clusters that END in `c` missed every one
 * of those, including the very common `set -euo pipefail` idiom.
 *
 * This is a LINEAR TOKEN SCAN, not one regex. Expressing "an interpreter, then
 * any number of option words, then a `-c` cluster" as a single pattern needs
 * quantified alternatives that can match the same text two ways, which
 * backtracks exponentially: an earlier version took 1.9s on 34 repeated
 * options and grew ~7x per four more — a CPU denial of service, since the
 * command string comes from the agent.
 */
const INTERPRETER_NAME = /^(?:.*\/)?(?:ba|z|k|a|da)?sh$/i;

/** Locate `sh -c <quoted body>` invocations that sit at a command position. */
function findInterpreterBodies(text: string): string[] {
  const bodies: string[] = [];
  // Split on shell operators / newlines: each piece starts at a command
  // position, which is exactly where an interpreter has to appear.
  for (const segment of text.split(/[;|&(\n]/)) {
    const trimmed = segment.trim();
    if (!trimmed) continue;

    // Walk whitespace-separated tokens: interpreter, then options, then the
    // quoted body. Bounded by token count, so no backtracking.
    const tokens = trimmed.split(/\s+/);
    if (!tokens[0] || !INTERPRETER_NAME.test(tokens[0])) continue;

    let sawDashC = false;
    for (let i = 1; i < tokens.length; i++) {
      const token = tokens[i] as string;
      if (token.startsWith("-")) {
        // A short-option cluster containing `c` means the next non-option
        // argument is the command body. Long options (`--login`) never are.
        if (!token.startsWith("--") && token.includes("c")) sawDashC = true;
        continue;
      }
      if (!sawDashC) break; // an operand before -c: not an interpreter body
      // Everything from here is the body; recover it from the original
      // segment so inner spacing and quotes survive the token split.
      const idx = trimmed.indexOf(token);
      const rest = idx === -1 ? token : trimmed.slice(idx);
      const quoted = /^(['"])([\s\S]*)\1$/.exec(rest.trim());
      bodies.push(quoted ? (quoted[2] as string) : rest.trim());
      break;
    }
  }
  return bodies;
}

