import { test } from "bun:test";
import { isDirectPackageInstallCommand } from "./src/runtime/tool-policy";

test("perf: no superlinear blowup", () => {
  for (const n of [34, 100, 400, 2000]) {
    const cmd = `bash ${"-e ".repeat(n)}nope`;
    const t0 = performance.now();
    isDirectPackageInstallCommand(cmd);
    console.log(`n=${n}  ${(performance.now() - t0).toFixed(2)}ms`);
  }
});

test("behavior preserved", () => {
  const deny = [
    "bash -c 'nix run x'",
    "bash -lc 'nix run x'",
    "bash -ce 'nix run x'",
    "sh -cx 'uvx cowsay'",
    "bash -e -c 'nix run x'",
    "bash -o pipefail -c 'nix run x'",
    "bash -euo pipefail -c 'uvx x'",
    "true; bash -ce 'nix run x'",
    "echo ok\nsh -c 'nix run x'",
    "/bin/bash -c 'nix run x'",
    'bash -c "nix run x"',
    "nix run x",
    "uvx cowsay",
    "true; nix run x",
    "(nix shell nixpkgs#hello)",
  ];
  const allow = [
    "echo bash -ce 'nix run x'",
    "git commit -m 'bash -ce nix run'",
    "bash -x script.sh",
    "bash -c 'echo hello'",
    "git commit -m 'document nix shell support'",
    "echo done # nix run x",
    "echo sh -c 'nix run x'",
    "nixfmt file.nix",
    "bash --version",
  ];
  let bad = 0;
  for (const c of deny) {
    if (!isDirectPackageInstallCommand(c)) {
      console.log("MISS", JSON.stringify(c));
      bad++;
    }
  }
  for (const c of allow) {
    if (isDirectPackageInstallCommand(c)) {
      console.log("FP  ", JSON.stringify(c));
      bad++;
    }
  }
  console.log(bad === 0 ? "ALL CLEAN" : `${bad} problems`);
});

