import { expect, test } from "bun:test";
import { isDirectPackageInstallCommand } from "./src/runtime/tool-policy";

test("anchoring fix works on top of merged main", () => {
  const allow = [
    "echo uvx cowsay",
    "git log --grep nix run",
    "man nix run",
    "echo npm install",
    "echo apt install is bad",
    "printf uvx",
  ];
  const deny = [
    "nix run x",
    "nix shell nixpkgs#hello",
    "uvx cowsay",
    "npm install lodash",
    "apt install curl",
    "true; nix run x",
    "true && uvx x",
    "(nix shell nixpkgs#hello)",
    "true\nnix run x",
    "bash -c 'nix run x'",
    "bash -euo pipefail -c 'uvx x'",
    "sudo nix run x",
  ];
  const bad: string[] = [];
  for (const c of allow)
    if (isDirectPackageInstallCommand(c)) bad.push(`FP   ${JSON.stringify(c)}`);
  for (const c of deny)
    if (!isDirectPackageInstallCommand(c)) bad.push(`MISS ${JSON.stringify(c)}`);
  for (const b of bad) console.log(b);
  console.log(bad.length === 0 ? "ALL CLEAN" : `${bad.length} problems`);
  expect(bad).toEqual([]);
});

test("ReDoS fix survived the cherry-pick", () => {
  for (const cmd of [
    `\nsh ${"- ".repeat(2000)}x`,
    `bash ${"-e ".repeat(2000)}nope`,
  ]) {
    const t0 = performance.now();
    isDirectPackageInstallCommand(cmd);
    const ms = performance.now() - t0;
    console.log(`len=${cmd.length}  ${ms.toFixed(2)}ms`);
    expect(ms).toBeLessThan(1000);
  }
});

