import { isDirectPackageInstallCommand } from "./src/runtime/tool-policy";

test("keyword positions, argument text, and perf", () => {
  const deny = [
    // keyword command positions (the blocker)
    "if nix run x; then :; fi",
    "{ nix run x; }",
    "! nix run x",
    "for i in 1; do nix run x; done",
    "while :; do uvx x; done",
    "then nix run x",
    "else uvx x",
    // ordinary positions
    "nix run x",
    "  nix run x",
    "uvx cowsay",
    "npm install lodash",
    "apt install curl",
    "sudo nix run x",
    "true; nix run x",
    "true && uvx x",
    "echo hi | uvx x",
    "(nix shell nixpkgs#hello)",
    "true\nnix run x",
    "bash -c 'nix run x'",
    "bash -euo pipefail -c 'uvx x'",
  ];
  const allow = [
    // the anchoring fix
    "echo uvx cowsay",
    "git log --grep nix run",
    "man nix run",
    "echo npm install",
    "printf uvx",
    // keyword lookalikes must not open a position
    "echo iffy nix run",
    "echo dofile nix run",
    // preserved from #2259
    "git commit -m 'document nix shell support'",
    "echo done # nix run x",
    "echo sh -c 'nix run x'",
    "nixfmt file.nix",
    "npm run build",
  ];
  const bad: string[] = [];
  for (const c of deny)
    if (!isDirectPackageInstallCommand(c)) bad.push(`MISS ${JSON.stringify(c)}`);
  for (const c of allow)
    if (isDirectPackageInstallCommand(c)) bad.push(`FP   ${JSON.stringify(c)}`);
  for (const b of bad) console.log(b);
  console.log(bad.length === 0 ? "ALL CLEAN" : `${bad.length} problems`);
  expect(bad).toEqual([]);
});

test("still linear", () => {
  for (const cmd of [
