test("dedup: on collision the AGENT instance wins, not the skill's", () => {
  // The doc comment on resolveAgentGuardrails claims "operator intent
  // dominates" on a name collision, but that only holds because the agent
  // block runs before the skill block and the second is gated on
  // `!seen[stage].has(name)`. Reordering those two blocks would silently let
  // a skill shadow an operator's guardrail — and the count-only assertion in
  // the test above still passes under that reorder, so it cannot catch it.
  //
  // Precedence is observable only for the `builtin` arm: a skill `judge`
  // entry gets a hashed name (`skill:<name>:inline:pre-tool:<hash>`) that can
  // never collide with an operator's. And because both branches resolve the
  // SAME registry object for a builtin, the two instances have to be made
  // distinguishable — hence the split double below, which returns a marked
  // object from `resolve` (agent branch) versus `get` (skill branch).
  const agentInstance = { ...createNoopGuardrail("pre-tool", "secret-scan") };
  const skillInstance = { ...createNoopGuardrail("pre-tool", "secret-scan") };
  (agentInstance as { origin?: string }).origin = "agent";
  (skillInstance as { origin?: string }).origin = "skill";

  const split = {
    // Agent branch: aggregator calls registry.resolve(stage, enabledNames).
    resolve: () => [agentInstance],
    // Skill branch: aggregator calls registry.get("pre-tool", name).
    get: () => skillInstance,
  } as unknown as GuardrailRegistry;

  const skill: SkillConfig = {
    repo: "x/y",
    name: "github",
    enabled: true,
    guardrails: { "pre-tool": [{ kind: "builtin", name: "secret-scan" }] },
  };
  const out = resolveAgentGuardrails(
    { guardrails: ["secret-scan"] },
    [skill],
    split
  );

  const resolved = out.guardrails["pre-tool"].filter(
    (g) => g.name === "secret-scan"
  );
  expect(resolved).toHaveLength(1);
  expect((resolved[0] as { origin?: string }).origin).toBe("agent");
});

